{"code":"def evaluate_rule(data: Data) -> bool:
    """Determine if a loan requires a guarantor.

    Returns ``True`` when at least one of the following conditions holds:
    - applicant is younger than 25 years;
    - credit score (puntaje) is below 680;
    - requested amount (monto) exceeds six times the monthly income (ingreso);
    - employment type (empleo) is one of "informal", "temporario", "dependencia", "monotributista", "autonomo";
    - there was at least one credit rejection in the last 12 months.

    The only exception is when the applicant offers a pledged guarantee
    (``garantia_prendaria`` is ``True``); in that case a guarantor is never
    required.
    """
    if data["garantia_prendaria"]:
        return False
    if data["edad"] < 25:
        return True
    if data["puntaje"] < 680:
        return True
    if data["monto"] > 6 * data["ingreso"]:
        return True
    if data["empleo"] in {"informal", "temporario", "dependencia", "monotributista", "autonomo"}:
        return True
    if data["rechazos_12_meses"] > 0:
        return True
    return False"}

