{"code":"from decimal import Decimal, ROUND_DOWN

def evaluate_rule(data: Data) -> Decimal:
    saldo: Decimal = data["saldo"]
    # If the total balance is less than 500.00, the minimum payment is the full balance
    if saldo < Decimal('500.00'):
        return saldo.quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    five_percent: Decimal = saldo * Decimal('0.05')
    minimum: Decimal = five_percent if five_percent > Decimal('500.00') else Decimal('500.00')
    return minimum.quantize(Decimal('0.01'), rounding=ROUND_DOWN)"}

