{"code":"def evaluate_rule(data: Data) -> str:
    """Determine eligible education credit for 2025.

    Returns one of "AOTC", "LLC" or "Ninguno" according to the business rule.
    """
    tipo = data["tipo_declaracion"]
    magi = data["magi"]
    # Disqualifying conditions
    if tipo == "separada":
        return "Ninguno"
    if tipo == "conjunta":
        if magi >= 180000:
            return "Ninguno"
    else:
        if magi >= 90000:
            return "Ninguno"
    # AOTC eligibility
    if (
        not data["completo_4_anios"]
        and data["anios_aotc_pedidos"] < 4
        and data["programa_con_titulo"]
        and data["al_menos_medio_tiempo"]
        and not data["condena_drogas"]
    ):
        return "AOTC"
    return "LLC""}

