{"code":"from typing import TypedDict

def evaluate_rule(data: Data) -> bool:
    """Determina si el paciente cumple los criterios de alta.

    Requisitos:
    - al menos 24 horas sin fiebre
    - saturación de oxígeno >= 94%
    - tolera vía oral
    - dolor <= 3
    - no tiene drenajes
    - si vive solo, debe tener acompañante
    """
    if data["horas_sin_fiebre"] < 24:
        return False
    if data["saturacion"] < 94:
        return False
    if not data["tolera_via_oral"]:
        return False
    if data["dolor"] > 3:
        return False
    if data["tiene_drenajes"]:
        return False
    if data["vive_solo"] and not data["tiene_acompanante"]:
        return False
    return True"}

