{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> bool:
    """Return True if the patient satisfies all pre‑operative conditions.

    Conditions:
    1. Signed informed consent.
    2. Minimum 8 hours of fasting.
    3. Hemoglobin >= 10.0 g/dL.
    4. Not on anticoagulants.
    5. ASA risk class 1, 2 or 3.
    6. If age >= 70, cardiac evaluation must be true.
    """
    if not data["consentimiento"]:
        return False
    if data["horas_ayuno"] < 8:
        return False
    if data["hemoglobina"] < Decimal("10.0"):
        return False
    if data["anticoagulado"]:
        return False
    if data["riesgo_asa"] not in (1, 2, 3):
        return False
    if data["edad"] >= 70 and not data["evaluacion_cardiologica"]:
        return False
    return True"}

