{"code":"from decimal import Decimal
from typing import Final

def evaluate_rule(data: Data) -> Decimal:
    """Calculate the reimbursement amount for a study.

    Only the studies "laboratorio", "radiografia", "ecografia",
    "resonancia" and "tomografia" are eligible. The percentage depends on the
    plan: 90 % for "premium", 70 % for "intermedio" and 50 % for "basico".
    The result is rounded to two decimal places.
    """
    eligible: Final[set[str]] = {"laboratorio", "radiografia", "ecografia", "resonancia", "tomografia"}
    plan_percent: Final[dict[str, Decimal]] = {
        "premium": Decimal("90"),
        "intermedio": Decimal("70"),
        "basico": Decimal("50"),
    }

    if data["estudio"] not in eligible:
        return Decimal("0.0")

    percent: Decimal = plan_percent.get(data["plan"], Decimal("0"))
    reimbursement: Decimal = (data["costo"] * percent) / Decimal("100")
    return reimbursement.quantize(Decimal("0.01"))"}

