def evaluate_rule(data: Data) -> Decimal:
    """Calculate indemnization: damage minus deductible.
    If deductible >= damage, return Decimal('0.0')."""
    damage: Decimal = data['danio']
    deductible: int = data['deducible']
    deductible_dec: Decimal = Decimal(deductible)
    if deductible_dec >= damage:
        return Decimal('0.0')
    return damage - deductible_dec"}

