{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> Decimal:
    """Calcula la prima mensual de un seguro de vida.

    La prima se determina multiplicando la suma asegurada por una tasa
    que depende de la edad y, si la persona fuma, se le suma un recargo
    fijo de 2500 pesos.
    """
    edad: int = data["edad"]
    fuma: bool = data["fuma"]
    suma_asegurada: Decimal = Decimal(data["suma_asegurada"])

    if edad < 40:
        tasa: Decimal = Decimal("0.0008")
    elif edad < 60:
        tasa = Decimal("0.0015")
    else:
        tasa = Decimal("0.003")

    prima: Decimal = suma_asegurada * tasa
    if fuma:
        prima += Decimal("2500")
    return prima"}

