    prima_base = data.get('prima_base')
    if not isinstance(prima_base, Decimal):
        prima_base = Decimal(prima_base)
    factors = {
        'joven': Decimal('1.35'),
        'adulto': Decimal('1.00'),
        'mayor': Decimal('1.15')
