from typing import TypedDict

def evaluate_rule(data: Data) -> Decimal:
    franja: str = data["franja"]
    base: Decimal = data["prima_base"]
    factor_map: dict[str, Decimal] = {
        "joven": Decimal("1.35"),
        "adulto": Decimal("1.00"),
        "mayor": Decimal("1.15"),
    }
    if franja not in factor_map:
        raise ValueError(f"Franja desconocida: {franja}")
    factor: Decimal = factor_map[franja]
    result: Decimal = (base * factor).quantize(Decimal("0.01"))
    return result"}

