{"code":"from typing import TypedDict

def evaluate_rule(data: Data) -> bool:
    """Determine if a policy is automatically renewed.

    The policy renews automatically when there is no grave claim (`siniestro_grave` is False)
    and the insured either paid all installments on time (`pago_a_termino` is True) or has
    automatic debit enabled (`debito_automatico` is True).
    """
    if data["siniestro_grave"]:
        return False
    return data["pago_a_termino"] or data["debito_automatico"]"}

