{"code":"def evaluate_rule(data):
    from decimal import Decimal
    monto = Decimal(data['monto'])
    valor = Decimal(data['valor_vivienda'])
    if monto > valor * Decimal('0.8'):
        return False
    cuota_total = Decimal(data['cuota_nueva'] + data['cuotas_otras'])
    ingreso = Decimal(data['ingreso_hogar'])
    if cuota_total > ingreso * Decimal('0.4'):
        return False
    empleo = data['empleo'].lower()
    meses = data['meses_actividad']
    empleo_ok = False
    if empleo == 'dependencia':
        empleo_ok = True
    elif empleo in ('monotributista', 'autonomo') and meses >= 24:
        empleo_ok = True
    if not empleo_ok:
        return False
    if not (data['primera_vivienda'] or data['plazo_anios'] <= 20):
        return False
    return True"}

