{"code":"def evaluate_rule(data: Data) -> bool:
    """Return True if a guarantor is required for the loan."""
    if data["garantia_prendaria"]:
        return False
    age_cond = data["edad"] < 25
    score_cond = data["puntaje"] < 680
    amount_cond = data["monto"] > 6 * data["ingreso"]
    employment_cond = data["empleo"] in {"informal", "temporario", "dependencia", "monotributista", "autonomo"}
    reject_cond = data["rechazos_12_meses"] > 0
    return any((age_cond, score_cond, amount_cond, employment_cond, reject_cond))"}

