def evaluate_rule(data: Data) -> str:
    """Evalúa la regla de clasificación de riesgo crediticio.

    Args:
        data: Diccionario con las claves 'deudas_en_mora' (int) y 'puntaje' (int).

    Returns:
        Una letra que representa el riesgo: 'E', 'D', 'C', 'B' o 'A'.
    """
    deudas: int = data["deudas_en_mora"]
    puntaje: int = data["puntaje"]

    if deudas > 2:
        return "E"
    if puntaje < 500 or deudas == 2:
        return "D"
    if puntaje < 650:
        return "C"
    if puntaje < 750 or deudas == 1:
        return "B"
    return "A"
"}

