{"code":"from decimal import Decimal, ROUND_DOWN

def evaluate_rule(data: Data) -> Decimal:
    saldo: Decimal = data["saldo"]
    if saldo < Decimal("500"):
        return saldo.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
    five_percent: Decimal = saldo * Decimal("0.05")
    min_payment: Decimal = five_percent if five_percent > Decimal("500") else Decimal("500")
    return min_payment.quantize(Decimal("0.01"), rounding=ROUND_DOWN)"}

