{"code":"from decimal import Decimal

def evaluate_rule(data):
    cuota = data["cuota"]
    ingreso = data["ingreso"]
    if ingreso == 0:
        raise ValueError("Ingreso cannot be zero")
    relacion = cuota / ingreso
    if relacion <= Decimal('0.30'):
