{"code":"from typing import TypedDict

def evaluate_rule(data: Data) -> bool:
    """Return True if the taxpayer is eligible for the credit for other dependents in 2025.

    Eligibility requires:
    * The person is claimed as a dependent (es_dependiente).
    * U.S. situation is one of "ciudadano", "nacional" or "residente".
    * Identification type is one of "SSN", "SSN_sin_permiso_laboral", "ITIN" or "ATIN".
    * The person does **not** qualify for the child credit (es_hijo_calificable, age < 17, SSN).
    """
    # Determine if the person qualifies for the child credit, which precludes the other‑dependent credit.
    credit_child: bool = (
        data["es_hijo_calificable"]
        and data["edad"] < 17
        and data["identificacion"] == "SSN"
    )
    if credit_child:
        return False

    # Evaluate the conditions for the other‑dependent credit.
    return (
        data["es_dependiente"]
        and data["situacion"] in {"ciudadano", "nacional", "residente"}
        and data["identificacion"] in {"SSN", "SSN_sin_permiso_laboral", "ITIN", "ATIN"}
    )"}

