    ingreso: int = data["ingreso_bruto"]
    edad65: int = data["cantidad_65_o_mas"]

    if estado == "casado_separado":
        return ingreso >= 5

    base_thresholds: dict[str, int] = {
        "soltero": 15750,
        "jefe_de_hogar": 23625,
        "casado_conjunta": 31500,
        "viudo_calificado": 31500,
    }
    extra_per_person: dict[str, int] = {
        "soltero": 2000,
        "jefe_de_hogar": 2000,
        "casado_conjunta": 1600,
        "viudo_calificado": 1600,
    }

    if estado not in base_thresholds:
        return False

    total = base_thresholds[estado] + extra_per_person[estado] * edad65
    return ingreso >= total"}

