{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> Decimal:
    """Calculate deductible gambling losses for 2025.

    If the taxpayer itemizes deductions (``detalla_deducciones`` is ``True``),
    the deductible amount is the lesser of the gambling losses and the gambling
    winnings for the year. If the taxpayer does not itemize, the deductible is
    zero.
    """
    if not data["detalla_deducciones"]:
        return Decimal(0)
    deductible_int = min(data["perdidas_juego"], data["ganancias_juego"])
    return Decimal(deductible_int)
"}

