{"code":"from decimal import Decimal
from typing import TypedDict

def evaluate_rule(data: Data) -> Decimal:
    """Calculate indemnization based on best remuneration and months worked.

    The indemnization is the best monthly remuneration multiplied by the number
    of service years. Service years are derived from the worked months:
    * Every full 12 months counts as one year.
    * If the remaining months are greater than 3, an additional year is added.
    * If the total months are less than 3, the indemnization is zero.
    """
    months: int = data["meses_trabajados"]
    if months < 3:
        return Decimal("0.0")
    years: int = months // 12
    remainder: int = months % 12
    if remainder > 3:
        years += 1
    return data["mejor_remuneracion"] * Decimal(years)
"}

