{"code":"def evaluate_rule(data):
    from decimal import Decimal, ROUND_HALF_UP
    faltas_injustificadas = data.get('faltas_injustificadas')
    faltas_justificadas = data.get('faltas_justificadas')
    sueldo_basico = data.get('sueldo_basico')
    if faltas_injustificadas == 0 and faltas_justificadas == 0:
        adicional = (sueldo_basico * Decimal('0.10')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    elif faltas_injustificadas == 0 and faltas_justificadas == 1:
        adicional = (sueldo_basico * Decimal('0.05')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    else:
        adicional = Decimal('0.00')
    return adicional"}

