def evaluate_rule(data: Data) -> Decimal:
    """Calculate paracetamol dose per intake in mg.

    The dose is 15 mg per kilogram of weight, capped at 1000.0 mg.
    If the weight is less than 5.0 kg, the dose is 0.0 mg.
    """
    weight: Decimal = data["peso_kg"]
    if weight < Decimal('5.0'):
        return Decimal('0.0')
    dose: Decimal = weight * Decimal('15')
    if dose > Decimal('1000.0'):
        return Decimal('1000.0')
    return dose"}

