{"code":"def evaluate_rule(data):
    from decimal import Decimal
    allowed = {"laboratorio","radiografia","ecografia","resonancia","tomografia"}
    if data.get("estudio") not in allowed:
        return Decimal("0.0")
    plan = data.get("plan")
    perc_map = {"premium": Decimal("0.90"), "intermedio": Decimal("0.70"), "basico": Decimal("0.50")}
    percent = perc_map.get(plan, Decimal("0.0"))
    return (data.get("costo", Decimal("0.0")) * percent).quantize(Decimal("0.01"))"}

