{"code":"from decimal import Decimal
from typing import Final

ELIGIBLE_STUDIES: Final[set[str]] = {"laboratorio", "radiografia", "ecografia", "resonancia", "tomografia"}
PLAN_PERCENT: Final[dict[str, Decimal]] = {
    "premium": Decimal("90"),
    "intermedio": Decimal("70"),
    "basico": Decimal("50"),
}

def evaluate_rule(data: Data) -> Decimal:
    estudio: str = data["estudio"]
    if estudio not in ELIGIBLE_STUDIES:
        return Decimal("0.0")
    plan: str = data["plan"]
    percent: Decimal = PLAN_PERCENT.get(plan, Decimal("0"))
    reimbursement: Decimal = (data["costo"] * percent) / Decimal("100")
    return reimbursement.quantize(Decimal("0.01"))"}

