    if not data.get('cuotas_al_dia'):
        return False
    # Denuncia dentro de 72 horas
    if data.get('horas_hasta_denuncia', 0) > 72:
        return False
    # Monto reclamado no supera la suma asegurada
    if data.get('monto_reclamado', 0) > data.get('suma_asegurada', 0):
        return False
    # Denuncia policial obligatoria para robo o hurto
    tipo = data.get('tipo_siniestro', '').lower()
