def evaluate_rule(data: Data) -> Decimal:
    """Calculate the indemnization of a claim.

    The indemnization is the assessed damage (``danio``) minus the policy
    deductible (``deducible``).  If the deductible is greater than or equal to
    the damage, the result is ``Decimal('0.0')``.
    """
    damage: Decimal = data["danio"]
    deductible: int = data["deducible"]

    if deductible >= damage:
        return Decimal("0.0")
    return damage - Decimal(deductible)
"}

