{"code":"def evaluate_rule(data):
    from decimal import Decimal, getcontext
    getcontext().prec = 28
    edad = data.get('edad')
    fuma = data.get('fuma')
    suma = data.get('suma_asegurada')
    if edad < 40:
        rate = Decimal('0.0008')
    elif edad <= 59:
        rate = Decimal('0.0015')
    else:
        rate = Decimal('0.003')
    premium = Decimal(suma) * rate
    if fuma:
        premium += Decimal('2500')
    return premium"}

