{"code":"from decimal import Decimal, ROUND_HALF_EVEN
from typing import TypedDict

def evaluate_rule(data: Data) -> Decimal:
    franja: str = data["franja"]
    base: Decimal = data["prima_base"]
    if franja == "joven":
        factor: Decimal = Decimal("1.35")
    elif franja == "adulto":
        factor = Decimal("1.00")
    elif franja == "mayor":
        factor = Decimal("1.15")
    else:
        raise ValueError(f"Franja desconocida: {franja}")
    result: Decimal = (base * factor).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    return result"}

