{"code":"def evaluate_rule(data):
    casillas = data.get('casillas', 0)
    estado = data.get('estado_civil', '')
    # limitar casillas entre 0 y 4
    if casillas < 0:
        casillas = 0
    elif casillas > 4:
        casillas = 4
    # monto base según estado civil
    if estado in ('casado_conjunta', 'viudo_calificado'):
        base = 31500
    elif estado == 'jefe_de_hogar':
        base = 23625
    elif estado in ('soltero', 'casado_separado'):
        base = 15750
    else:
        raise ValueError('Estado civil desconocido')
    # adicional por casilla
    if estado in ('soltero', 'jefe_de_hogar'):
        extra_per = 2000
    else:
        extra_per = 1600
    total = base + extra_per * casillas
    return total"}

