{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> Decimal:
    """Calculate presentismo additional payment.

    Returns the amount in pesos with cents as Decimal.
    """
    faltas_injustificadas: int = data["faltas_injustificadas"]
    faltas_justificadas: int = data["faltas_justificadas"]
    sueldo_basico: Decimal = data["sueldo_basico"]

    if faltas_injustificadas == 0 and faltas_justificadas == 0:
        return (sueldo_basico * Decimal("0.10")).quantize(Decimal("0.01"))
    if faltas_injustificadas == 0 and faltas_justificadas == 1:
        return (sueldo_basico * Decimal("0.05")).quantize(Decimal("0.01"))
    return Decimal("0.00")"}

