from typing import TypedDict

Data = TypedDict("Data", {"comidas": int, "kilometros": int})

def evaluate_rule(data: Data) -> Decimal:
    """Calculate viáticos for a work trip.

    Returns 0.0 if the distance is less than 50 km, otherwise
    350.50 per km plus 25000 per meal.
    """
    if data["kilometros"] < 50:
        return Decimal("0.0")
    km_cost: Decimal = Decimal("350.50") * Decimal(data["kilometros"])
    meal_cost: Decimal = Decimal("25000") * Decimal(data["comidas"])
    return km_cost + meal_cost"}

