{"code":"from typing import TypedDict

def evaluate_rule(data: Data) -> str:
    """Devuelve la especialidad a la que se deriva el paciente.

    - Si la edad es menor a 15 años, siempre se deriva a "Pediatría".
    - Para mayores o iguales a 15 años, la derivación depende del motivo.
    """
    edad: int = data["edad"]
    motivo: str = data["motivo"]

    if edad < 15:
        return "Pediatría"

    cardio = {"dolor_toracico", "palpitaciones", "hipertension"}
    neurologia = {"cefalea", "convulsiones", "mareos", "perdida_de_memoria"}
    neumologia = {"tos_cronica", "disnea", "asma"}
    dermatologia = {"erupcion", "picazon", "lunar_cambiante", "acne"}

    if motivo in cardio:
        return "Cardiología"
    if motivo in neurologia:
        return "Neurología"
    if motivo in neumologia:
        return "Neumonología"
    if motivo in dermatologia:
        return "Dermatología"
    return "Clínica médica""}

