{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> str:
    """Clasifica el nivel de IMC según peso, altura y sexo.

    Args:
        data: Diccionario tipado con las claves 'altura_m', 'peso_kg' y 'sexo'.
    Returns:
        Una cadena con la clasificación correspondiente.
    """
    altura: Decimal = data['altura_m']
    peso: Decimal = data['peso_kg']
    sexo: str = data['sexo']

    if altura <= Decimal('0'):
        raise ValueError('altura_m debe ser mayor que cero')

    bmi: Decimal = peso / (altura * altura)

    if bmi >= Decimal('30'):
        return 'Obesidad'

    if bmi < Decimal('18.5'):
        if sexo == 'masculino':
            return 'Bajo peso severo'
        if sexo == 'femenino':
            return 'Bajo peso'
        raise ValueError('sexo debe ser "masculino" o "femenino"')

    if bmi < Decimal('25'):
        # 18.5 <= bmi < 25
        if sexo == 'masculino':
            return 'Bajo peso'
        if sexo == 'femenino':
            return 'Normal'
        raise ValueError('sexo debe ser "masculino" o "femenino"')

    # 25 <= bmi < 30
    if sexo == 'masculino':
        return 'Normal'
    if sexo == 'femenino':
        return 'Sobrepeso'
    raise ValueError('sexo debe ser "masculino" o "femenino"')"}

