def evaluate_rule(data: Data) -> Decimal:
    """Calculate the reimbursement amount for a study.

    Only the following studies are eligible: "laboratorio", "radiografia",
    "ecografia", "resonancia" and "tomografia". The reimbursement percentage
    depends on the plan: 90% for "premium", 70% for "intermedio" and 50% for
    "basico". The result is rounded to two decimal places.
    """
    eligible_studies: set[str] = {
        "laboratorio",
        "radiografia",
        "ecografia",
        "resonancia",
        "tomografia",
    }
    if data["estudio"] not in eligible_studies:
        return Decimal("0.00")

    plan_percentages: dict[str, Decimal] = {
        "premium": Decimal("0.90"),
        "intermedio": Decimal("0.70"),
        "basico": Decimal("0.50"),
    }
    percentage: Decimal = plan_percentages.get(data["plan"], Decimal("0"))
    reimbursement: Decimal = (data["costo"] * percentage).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )
    return reimbursement"}

{"code":"from decimal import Decimal, ROUND_HALF_UP
from typing import TypedDict

def evaluate_rule(data: Data) -> Decimal:
    """Calculate the reimbursement amount for a study.

    Only the following studies are eligible: "laboratorio", "radiografia",
    "ecografia", "resonancia" and "tomografia". The reimbursement percentage
    depends on the plan: 90% for "premium", 70% for "intermedio" and 50% for
    "basico". The result is rounded to two decimal places.
    """
    eligible_studies: set[str] = {
        "laboratorio",
        "radiografia",
        "ecografia",
        "resonancia",
        "tomografia",
    }
    if data["estudio"] not in eligible_studies:
        return Decimal("0.00")

    plan_percentages: dict[str, Decimal] = {
        "premium": Decimal("0.90"),
        "intermedio": Decimal("0.70"),
        "basico": Decimal("0.50"),
    }
    percentage: Decimal = plan_percentages.get(data["plan"], Decimal("0"))
    reimbursement: Decimal = (data["costo"] * percentage).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )
    return reimbursement"}

