def evaluate_rule(data: Data) -> bool:
    """Return True if claim payment is approved according to business rules."""
    within_time: bool = data["horas_hasta_denuncia"] <= 72
    cuotas_ok: bool = data["cuotas_al_dia"]
    monto_ok: bool = data["monto_reclamado"] <= data["suma_asegurada"]
    if data["tipo_siniestro"] in ("robo", "hurto"):
        denuncia_ok: bool = data["denuncia_policial"]
    else:
        denuncia_ok = True
    if data["poliza"] == "premium":
        reclamo_ok: bool = True
    else:
        reclamo_ok = not data["otro_reclamo_abierto"]
    return all((within_time, cuotas_ok, monto_ok, denuncia_ok, reclamo_ok))"}

