{"code":"def evaluate_rule(data):
    covered_events = {"incendio","robo","rayo","explosion","granizo","danio_por_agua","rotura_de_cristales"}
    evento = data.get("evento")
    if evento not in covered_events:
        return False
    if not data.get("poliza_vigente", False):
        return False
    if data.get("dias_deshabitada", 0) > 60:
        return False
    if evento == "robo" and not data.get("cerradura_seguridad", False):
        return False
    return True"}

