{"code":"from decimal import Decimal, ROUND_HALF_UP

def evaluate_rule(data):
    edad = data['edad']
    fuma = data['fuma']
    suma = data['suma_asegurada']
    # determinar tasa según edad
    if edad < 40:
        tasa = Decimal('0.0008')
    elif edad <= 59:
        tasa = Decimal('0.0015')
    else:
        tasa = Decimal('0.003')
    prima = Decimal(suma) * tasa
    if fuma:
        prima += Decimal('2500')
    # redondear a centavos
    prima = prima.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return prima"}

