{"code":"from decimal import Decimal, ROUND_DOWN

def evaluate_rule(data: Data) -> Decimal:
    """
    Calculate the minimum payment for a credit‑card statement.

    - If the total balance (``saldo``) is less than 500.00, the payment is the full balance.
    - Otherwise the payment is the greater of:
        * 5 % of the balance
        * 500.00
    The result is expressed with two decimal places (centavos) and is truncated
    (no rounding) to avoid rounding up.
    """
    saldo: Decimal = data["saldo"]
    limit: Decimal = Decimal("500.00")
    if saldo < limit:
        return saldo.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
    five_percent: Decimal = (saldo * Decimal("0.05")).quantize(
        Decimal("0.01"), rounding=ROUND_DOWN
    )
    return max(five_percent, limit)
"}

