{"code":"def evaluate_rule(data):
    estado = data.get("estado_civil", "").lower()
    if estado == "casado":
        if data.get("presentan_juntos"):
            return "Casado conjunta"
        else:
            if (not data.get("conyuge_vivio_ultimos_6_meses")
                    and data.get("paga_mas_mitad_hogar")
                    and data.get("tiene_hijo_dependiente")):
                return "Jefe de hogar"
            else:
                return "Casado separado"
    elif estado == "viudo":
        anio = data.get("anio_muerte_conyuge", 0)
        if anio == 2025:
            return "Casado conjunta"
        elif anio in (2023, 2024) and data.get("tiene_hijo_dependiente") and data.get("paga_mas_mitad_hogar"):
            return "Viudo calificado"
    # Caso genérico para los demás estados civiles o viudo que no cumple condiciones anteriores
    if data.get("paga_mas_mitad_hogar") and data.get("tiene_persona_calificante"):
        return "Jefe de hogar"
    return "Soltero""}

