    """
    Determines fiscal residency for 2025.
    Returns "Residente" or "No residente".
    """
    # Exemption check
    if data["es_estudiante"]:
        if data["anios_exento_estudiante"] < 5:
            return "No residente"
    if data["es_docente_o_aprendiz"]:
        if data["anios_exento_ultimos_6"] < 2:
            return "No residente"
    # Substantial presence test
    if data["dias_2025"] >= 31:
        total = data["dias_2025"] + data["dias_2024"] / 3 + data["dias_2023"] / 6
        if total >= 183:
            return "Residente"
    return "No residente""}

