def evaluate_rule(data: Data) -> Decimal:
    """Calculate child and other dependent credit for 2025 before phase‑out."""
    credit: Decimal = Decimal(2200) * Decimal(data["hijos_menores_17"]) + Decimal(500) * Decimal(data["otros_dependientes"])
    threshold: int = 400_000 if data["declaracion_conjunta"] else 200_000
    excess: int = data["magi"] - threshold
    if excess > 0:
        reduction_units: int = (excess + 999) // 1000
        reduction: Decimal = Decimal(reduction_units * 50)
    else:
        reduction = Decimal(0)
    result: Decimal = credit - reduction
    if result < 0:
        result = Decimal(0)
    return result"}

