def evaluate_rule(data: Data) -> bool:
    """Return True if the employee receives the annual bonus according to the business rules."""
    # Worked at least 9 months
    if data["meses_trabajados"] < 9:
        return False
    # Evaluation must be "supera" or "cumple"
    if data["evaluacion"] not in ("supera", "cumple"):
        return False
    # No more than 5 unjustified absences
    if data["ausencias_injustificadas"] > 5:
        return False
    # No disciplinary sanctions
    if data["sanciones"]:
        return False
    # Area compliance at least 80%
    if data["cumplimiento_area"] < 80:
        return False
    # Must still be with the company, unless retired during the year
    if not (data["sigue_en_la_empresa"] or data["jubilado_en_el_anio"]):
        return False
    return True"}

