{"code":"from decimal import Decimal, ROUND_HALF_UP

def evaluate_rule(data: Data) -> Decimal:
    horas: int = data['horas']
    tipo_dia: str = data['tipo_dia']
    valor_hora: Decimal = data['valor_hora']

    if tipo_dia == "habil":
        recargo = Decimal('1.5')
    elif tipo_dia in {"sabado_tarde", "domingo", "feriado"}:
        recargo = Decimal('2.0')
    else:
        raise ValueError(f"Tipo de día no reconocido: {tipo_dia}")

    extra_pay: Decimal = Decimal(horas) * valor_hora * recargo
    return extra_pay.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)"}

