{"code":"from decimal import Decimal, ROUND_HALF_UP

def evaluate_rule(data):
    faltas_injustificadas = data.get('faltas_injustificadas', 0)
    faltas_justificadas = data.get('faltas_justificadas', 0)
    sueldo_basico = data.get('sueldo_basico', Decimal('0'))
    if faltas_injustificadas == 0 and faltas_justificadas == 0:
        porcentaje = Decimal('0.10')
    elif faltas_injustificadas == 0 and faltas_justificadas == 1:
        porcentaje = Decimal('0.05')
    else:
        return Decimal('0.00')
    adicional = (sueldo_basico * porcentaje).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return adicional"}

