{"code":"def evaluate_rule(data: Data) -> bool:
    """Return True if the patient meets all discharge criteria.

    Conditions:
    - At least 24 hours without fever.
    - Oxygen saturation >= 94%.
    - Tolerates oral feeding.
    - Pain score <= 3.
    - No drains placed.
    - If the patient lives alone, an accompanying person must be present.
    """
    if data["horas_sin_fiebre"] < 24:
        return False
    if data["saturacion"] < 94:
        return False
    if not data["tolera_via_oral"]:
        return False
    if data["dolor"] > 3:
        return False
    if data["tiene_drenajes"]:
        return False
    if data["vive_solo"] and not data["tiene_acompanante"]:
        return False
    return True"}

