{"code":"def evaluate_rule(data: Data) -> str:
    """Calculate BMI and classify according to gender."""
    from decimal import Decimal
    altura: Decimal = data["altura_m"]
    peso: Decimal = data["peso_kg"]
    sexo: str = data["sexo"]
    if altura <= Decimal('0'):
        raise ValueError("Altura must be positive")
    bmi: Decimal = peso / (altura * altura)
    if bmi >= Decimal('30'):
        return "Obesidad"
    if bmi < Decimal('18.5'):
        if sexo == "masculino":
            return "Bajo peso severo"
        if sexo == "femenino":
            return "Bajo peso"
        raise ValueError(f"Sexo desconocido: {sexo}")
    if bmi < Decimal('25'):
        if sexo == "masculino":
            return "Bajo peso"
        if sexo == "femenino":
            return "Normal"
        raise ValueError(f"Sexo desconocido: {sexo}")
    # 25 <= bmi < 30
    if sexo == "masculino":
        return "Normal"
    if sexo == "femenino":
        return "Sobrepeso"
    raise ValueError(f"Sexo desconocido: {sexo}")"}

