{"code":"def evaluate_rule(data):
    from decimal import Decimal, ROUND_HALF_UP
    estudio = data.get('estudio', '').strip().lower()
    plan = data.get('plan', '').strip().lower()
    costo = data.get('costo', Decimal('0'))
    allowed = {'laboratorio', 'radiografia', 'ecografia', 'resonancia', 'tomografia'}
    if estudio not in allowed:
        return Decimal('0.00')
    percentages = {'premium': Decimal('90'), 'intermedio': Decimal('70'), 'basico': Decimal('50')}
    pct = percentages.get(plan, Decimal('0'))
    reintegro = (costo * pct / Decimal('100')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return reintegro"}

