def evaluate_rule(data: Data) -> bool:
    """Return True if the loan amount complies with the 30% annual income limit.
    If the applicant has a mortgage guarantee, the limit is ignored.
    """
    if data['garantia_hipotecaria']:
        return True
    annual_income = Decimal(data['ingreso_mensual']) * Decimal(12)
    limit = annual_income * Decimal('0.30')
    return Decimal(data['monto']) <= limit"}

