{"code":"def evaluate_rule(data):
    tiene_ssn = data.get('tiene_ssn_valido', False)
    no_dependiente = not data.get('puede_ser_dependiente', True)
    dias = data.get('dias_en_eeuu', 0)
    ingreso_inv = data.get('ingreso_inversion', 0)
    ingreso_ganado = data.get('ingreso_ganado', 0)
    agi = data.get('agi', 0)
    declaracion_conjunta = data.get('declaracion_conjunta', False)
    edad = data.get('edad', 0)
    edad_conyuge = data.get('edad_conyuge', 0)

    # Requisitos básicos
    if not tiene_ssn:
        return False
    if not no_dependiente:
        return False
    if dias < 183:
        return False
    if ingreso_inv > 11950:
        return False
    if ingreso_ganado <= 0:
        return False

    # Límites de ingresos según tipo de declaración
    limite = 26214 if declaracion_conjunta else 19104
    if ingreso_ganado >= limite:
        return False
    if agi >= limite:
        return False

    # Requisitos de edad
    if declaracion_conjunta:
        edad_ok = (25 <= edad < 65) or (25 <= edad_conyuge < 65)
    else:
        edad_ok = 25 <= edad < 65
    if not edad_ok:
        return False

    return True"}

