{"code":"from decimal import Decimal
from typing import TypedDict

def evaluate_rule(data: Data) -> Decimal:
    """Calculate additional tax for early IRA withdrawal."""
    exempt_motives = {"educacion_superior", "discapacidad_total", "fallecimiento_del_titular", "seguro_medico_desempleado"}
    age: Decimal = data["edad"]
    amount: Decimal = data["monto"]
    motive: str = data["motivo"]
    if age < Decimal("59.5") and motive not in exempt_motives:
        return (amount * Decimal("0.10")).quantize(Decimal("0.01"))
    return Decimal("0.0")"}

