{"code":"from typing import TypedDict

def evaluate_rule(data: Data) -> bool:
    """Return ``True`` if the payment to the family member counts for the dependent‑care credit.

    The payment does **not** count when any of the following conditions is true:
    1. The caregiver is a dependent of the taxpayer.
    2. The caregiver is the taxpayer's child **and** was younger than 19 on 31 December of the tax year.
    3. The caregiver was the taxpayer's spouse at any time during the year.
    4. The caregiver is the parent of the child being cared for **and** that child is younger than 13.
    """
    if data["cuidador_es_dependiente"]:
        return False
    if data["cuidador_es_hijo"] and data["edad_cuidador"] < 19:
        return False
    if data["cuidador_fue_conyuge"]:
        return False
    if data["cuidador_es_padre_del_nino"] and data["edad_nino"] < 13:
        return False
    return True"}

