EstadoCivil = Literal["soltero", "jefe_de_hogar", "casado_conjunta", "viudo_calificado", "casado_separado"]

def evaluate_rule(data: Data) -> bool:
    estado: EstadoCivil = data["estado_civil"]
    ingreso: int = data["ingreso_bruto"]
    cant_65: int = data["cantidad_65_o_mas"]
    if estado == "casado_separado":
        return ingreso >= 5
    base_thresholds: dict[EstadoCivil, int] = {
        "soltero": 15750,
        "jefe_de_hogar": 23625,
        "casado_conjunta": 31500,
        "viudo_calificado": 31500,
    }
    extra_per_person: dict[EstadoCivil, int] = {
        "soltero": 2000,
        "jefe_de_hogar": 2000,
        "casado_conjunta": 1600,
        "viudo_calificado": 1600,
    }
    base = base_thresholds[estado]
    extra = extra_per_person[estado]
    if estado in ("soltero", "jefe_de_hogar"):
        persons = 1 if cant_65 >= 1 else 0
    else:
        persons = cant_65
    threshold = base + extra * persons
    return ingreso >= threshold"}

