{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> str:
    """Assign triage color based on patient vital signs.

    The rules are evaluated in the given order; the first matching rule
    determines the color.
    """
    if not data["consciente"] or data["saturacion"] < 90:
        return "Rojo"
    if data["saturacion"] < 94 or data["frecuencia_cardiaca"] > 120 or data["dolor"] >= 8:
        return "Naranja"
    if data["temperatura"] >= Decimal("38.5") or data["dolor"] >= 5:
        return "Amarillo"
    return "Verde""}

