{"code":"from decimal import Decimal

def evaluate_rule(data: Data) -> Decimal:
    """Calculate paracetamol dose per administration in mg.

    The dose is 15 mg per kilogram of body weight, capped at 1000 mg.
    For patients weighing less than 5 kg the dose is 0 mg.
    """
    peso: Decimal = data["peso_kg"]
    min_weight: Decimal = Decimal("5.0")
    max_dose: Decimal = Decimal("1000.0")
    dose_per_kg: Decimal = Decimal("15")
    if peso < min_weight:
        return Decimal("0.0")
    dose: Decimal = peso * dose_per_kg
    if dose > max_dose:
        dose = max_dose
    return dose"}

