{"code":"from decimal import Decimal

def evaluate_rule(data):
    estudio = data.get('estudio','').lower()
    plan = data.get('plan','').lower()
    costo = data.get('costo', Decimal('0'))
    estudios_validos = {'laboratorio','radiografia','ecografia','resonancia','tomografia'}
    if estudio not in estudios_validos:
        return Decimal('0.0')
    porcentajes = {'premium': Decimal('90'), 'intermedio': Decimal('70'), 'basico': Decimal('50')}
    porcentaje = porcentajes.get(plan, Decimal('0'))
    return (costo * porcentaje / Decimal('100')).quantize(Decimal('0.01'))"}

