    poliza: str = data["poliza"]
    previos: int = data["siniestros_previos"]

    if poliza == "todo_riesgo":
        if previos == 0:
            base = Decimal(150000)
        elif previos == 1:
            base = Decimal(300000)
        else:
            base = Decimal(500000)
    elif poliza == "terceros_completo":
        if previos == 0:
            base = Decimal(80000)
        else:
            base = Decimal(160000)
    elif poliza == "terceros":
        base = Decimal(0)
    else:
        raise ValueError(f"Poliza desconocida: {poliza}")

    if edad < 25:
        base += Decimal(50000)

    return base"}

